async function onFilesChanged(e: Event): Promise<void> {
	const input = e.target as HTMLInputElement;
	const files = input.files;
	if (!files) return;
	uploading = true;
	error = null;

	// #{#dtv2a} Upload receipts — suspicious dates are silently flagged, no dialog shown
	// Each file is processed independently so one failure doesn't abort the batch.
	const failures: string[] = [];
	for (const file of files) {
		try {
			const receipt = await ReceiptService.get().uploadAndCreate(file);
			allReceipts = [receipt, ...allReceipts];
		} catch (err: any) {
			console.error('Failed to upload receipt', file.name, err);
			failures.push(`${file.name}: ${err?.message ?? 'Failed to upload'}`);
		}
	}
	if (failures.length > 0) {
		error = `Failed ${failures.length} of ${files.length} receipt(s):\n${failures.join('\n')}`;
	}
	uploading = false;

	input.value = '';
}

// #{#sec1a} Signed URL cache for receipt images
let signedUrls: Record<string, string> = $state({});

