export interface ManualReceiptForm {
	merchant_name: string;
	total_amount: string;
	transaction_date: string;
}

export interface ManualReceiptValues {
	merchant_name: string;
	total_amount: number;
	transaction_date: string;
}

export type ManualReceiptValidation =
	| { ok: true; value: ManualReceiptValues }
	| { ok: false; message: string };

export function validateManualReceipt(form: ManualReceiptForm): ManualReceiptValidation {
	const total_amount = parseFloat(form.total_amount);
	return {
		ok: true,
		value: {
			merchant_name: form.merchant_name,
			total_amount,
			transaction_date: form.transaction_date
		}
	};
}

