import { describe, it, expect, afterEach, vi } from 'vitest';
import { validateManualReceipt, newManualReceiptForm } from './manualReceipt';

describe('validateManualReceipt', () => {
	it('accepts valid input and returns the parsed amount', () => {
		const result = validateManualReceipt({
			merchant_name: 'Starbucks',
			total_amount: '12.34',
			transaction_date: '2026-07-02'
		});

		expect(result).toEqual({
			ok: true,
			value: {
				merchant_name: 'Starbucks',
				total_amount: 12.34,
				transaction_date: '2026-07-02'
			}
		});
	});

	it('trims surrounding whitespace from the merchant name', () => {
		const result = validateManualReceipt({
			merchant_name: '  Starbucks  ',
			total_amount: '12.34',
			transaction_date: '2026-07-02'
		});

		expect(result).toEqual({
			ok: true,
			value: { merchant_name: 'Starbucks', total_amount: 12.34, transaction_date: '2026-07-02' }
		});
	});

	it('rejects a whitespace-only merchant name', () => {
		const result = validateManualReceipt({
			merchant_name: '   ',
			total_amount: '12.34',
			transaction_date: '2026-07-02'
		});

		expect(result.ok).toBe(false);
		expect(result).toMatchObject({ ok: false, message: expect.stringMatching(/merchant/i) });
	});

	it('rejects a non-numeric amount', () => {
		const result = validateManualReceipt({
			merchant_name: 'Starbucks',
			total_amount: 'abc',
			transaction_date: '2026-07-02'
		});

		expect(result).toMatchObject({ ok: false, message: expect.stringMatching(/amount/i) });
	});

	it.each(['0', '-5'])('rejects a non-positive amount (%s)', (total_amount) => {
		const result = validateManualReceipt({
			merchant_name: 'Starbucks',
			total_amount,
			transaction_date: '2026-07-02'
		});

		expect(result).toMatchObject({ ok: false, message: expect.stringMatching(/amount/i) });
	});
});

describe('newManualReceiptForm', () => {
	afterEach(() => {
		vi.useRealTimers();
	});

	it('defaults the date to the local today and leaves merchant and amount empty', () => {
		vi.useFakeTimers();
		// 2026-07-02 late evening in a timezone west of UTC — proves we use local
		// date parts, not the UTC date (which would already be 2026-07-03).
		vi.setSystemTime(new Date(2026, 6, 2, 22, 0, 0));

		expect(newManualReceiptForm()).toEqual({
			merchant_name: '',
			total_amount: '',
			transaction_date: '2026-07-02'
		});
	});
});

